-- Fictional, bilingual catalog for the local Maison Sillage demo.
-- Stable slugs and conflict updates make this safe to re-run. No customer accounts are seeded.
insert into public.categories (slug, name_ar, name_en, description_ar, description_en, active, sort_order)
values
  ('women', 'نسائي', 'For her', 'عطور رقيقة ومتوازنة لكل يوم.', 'Considered fragrances for everyday rituals.', true, 10),
  ('men', 'رجالي', 'For him', 'تركيبات دافئة ومنعشة بتفاصيل واضحة.', 'Warm and fresh compositions with character.', true, 20),
  ('unisex', 'للجنسين', 'Unisex', 'روائح تتجاوز التصنيفات وتترك أثرها الخاص.', 'Expressive scents beyond convention.', true, 30)
on conflict (slug) do update set name_ar=excluded.name_ar, name_en=excluded.name_en,
  description_ar=excluded.description_ar, description_en=excluded.description_en,
  active=excluded.active, sort_order=excluded.sort_order;

with catalog(slug, brand, name_ar, name_en, short_ar, short_en, description_ar, description_en, category_slug, gender, family, season, occasion, concentration, longevity_min, longevity_max, projection, featured, priority) as (
  values
  ('amber-veil','Maison Sillage','حجاب العنبر','Amber Veil','عنبر ناعم يلتقي بزهور بيضاء ولمسة من الفانيلا.','Soft amber meets white florals and a trace of vanilla.','يفتتح العطر ببرغموت مضيء، ثم يكشف عن قلب من الياسمين وخشب الصندل. يترك العنبر والفانيلا دفئًا قريبًا من البشرة.','Bright bergamot opens into jasmine and sandalwood, settling into a skin-close warmth of amber and vanilla.','women','women','amber floral','autumn,winter','evening,occasion','Eau de Parfum',7,9,3,true,100),
  ('fig-at-dusk','Maison Sillage','تين الغروب','Fig at Dusk','أوراق التين الخضراء مع خشب كريمي ومسك هادئ.','Green fig leaves with creamy woods and quiet musk.','تلتقي أوراق التين بلمسة من الهيل في بداية خضراء، يليها قلب ناعم من السوسن وقاعدة من أخشاب الأرز والمسك.','Fig leaf and cardamom make a green opening, softened by iris and a clean cedar-musk base.','unisex','unisex','woody green','spring,summer','day,office','Eau de Parfum',6,8,2,true,95),
  ('rose-after-rain','Maison Sillage','ورد بعد المطر','Rose After Rain','ورد شفاف وبتلات مبللة فوق قاعدة ترابية أنيقة.','Airy rose and wet petals over an elegant earthy base.','رائحة ورد ندية لا تطغى، تتوازن مع الفلفل الوردي والباتشولي الناعم لتناسب لحظات النهار الهادئة.','A dewy, never-heavy rose balanced by pink pepper and gentle patchouli for quiet daytime moments.','women','women','floral chypre','spring,autumn','day,occasion','Eau de Parfum',6,8,3,false,90),
  ('cedar-atelier','Maison Sillage','مشغل الأرز','Cedar Atelier','أرز جاف وبهارات ناعمة بطابع خشبي مصقول.','Dry cedar and gentle spice in a polished woody blend.','يبدأ ببرغموت وفلفل أسود، ثم يستقر على أخشاب الأرز والفيتيفر. إحساس مرتب يدوم دون مبالغة.','Bergamot and black pepper lead to cedar and vetiver. A composed presence that lasts without excess.','men','men','woody spicy','autumn,winter','office,evening','Eau de Parfum',7,10,3,true,85),
  ('salted-citrus','Maison Sillage','حمضيات مالحة','Salted Citrus','حمضيات مشرقة ونفحة بحرية خفيفة ومسك نظيف.','Bright citrus with a light sea breeze and clean musk.','ليمون وماندرين بلمسة مالحة منعشة، يرافقهما زهر البرتقال وقاعدة خفيفة من المسك.','Lemon and mandarin get a breezy mineral edge, joined by orange blossom and a light musk base.','unisex','unisex','citrus aquatic','spring,summer','day,travel','Eau de Toilette',4,6,2,false,80),
  ('saffron-library','Maison Sillage','مكتبة الزعفران','Saffron Library','زعفران دافئ وجلد ناعم وأخشاب محبّرة.','Warm saffron, soft suede and inky woods.','زعفران وهيل في المقدمة، ثم جلد ناعم وأخشاب غاياك. تركيبة مسائية دافئة ذات حضور متزن.','Saffron and cardamom meet soft suede and guaiac wood in a balanced evening composition.','men','men','leather spicy','autumn,winter','evening,occasion','Extrait de Parfum',9,12,4,false,75),
  ('linen-musk','Maison Sillage','مسك الكتان','Linen Musk','مسك قطني ناعم مع زهر البرتقال ولمحة ألدهيدية.','Soft cotton musk with orange blossom and a sheer aldehydic lift.','بداية نظيفة من الألدهيدات والبرغموت، قلب زهر البرتقال، وقاعدة مسك تشبه دفء القماش النظيف.','Clean aldehydes and bergamot lead to orange blossom and a musk base reminiscent of fresh linen.','women','women','musky floral','spring,summer','day,office','Eau de Parfum',5,7,2,false,70),
  ('cocoa-ember','Maison Sillage','جمر الكاكاو','Cocoa Ember','كاكاو جاف وحبوب تونكا وعنبر معتّق.','Dry cocoa, tonka bean and aged amber.','كاكاو غير محلى يلتقي بالقرفة وحبوب التونكا، ثم يهدأ على قاعدة من العنبر وخشب الصندل.','Unsweetened cocoa meets cinnamon and tonka before settling over amber and sandalwood.','unisex','unisex','gourmand amber','autumn,winter','evening,occasion','Eau de Parfum',8,10,3,false,65),
  ('jasmine-courtyard','Maison Sillage','ياسمين الدار','Jasmine Courtyard','ياسمين ليلي مع زهر البرتقال وخشب شفاف.','Night-blooming jasmine with orange blossom and sheer woods.','ياسمين عربي وزهر برتقال منعش فوق أخشاب بيضاء. باقة زهرية مشرقة بلمسة كريمية.','Arabian jasmine and fresh orange blossom rest on white woods for a luminous, softly creamy floral.','women','women','white floral','spring,summer','day,occasion','Eau de Parfum',7,9,3,false,60),
  ('oud-horizon','Maison Sillage','أفق العود','Oud Horizon','عود ناعم يلتقي بالورد واللابدانوم.','Polished oud meets rose and labdanum.','خشب العود بملمس ناعم، يرافقه ورد دمشقي ولمسة راتنجية. عمق شرقي هادئ ومتدرج.','Smooth oud wood is paired with Damask rose and resinous labdanum for a measured oriental depth.','men','men','oud woody','autumn,winter','evening,occasion','Extrait de Parfum',10,12,4,false,55),
  ('green-tea-stillness','Maison Sillage','سكينة الشاي الأخضر','Green Tea Stillness','شاي أخضر ونيرولي ولمسة أعشاب هادئة.','Green tea, neroli and quiet aromatic herbs.','أوراق شاي خضراء ونيرولي مع لمسة نعناع خفيفة، تنساب إلى مسك وخشب أرز شفاف.','Green tea leaves and neroli with a touch of mint drift into sheer cedar and musk.','unisex','unisex','aromatic green','spring,summer','day,office','Eau de Toilette',4,6,2,false,50),
  ('velvet-iris','Maison Sillage','سوسن مخملي','Velvet Iris','سوسن بودري مع برقوق وخشب صندل دافئ.','Powdered iris with plum and warm sandalwood.','سوسن ناعم وبرقوق داكن في قلب متوازن، مع قاعدة كريمية من الصندل والمسك.','Soft iris and dark plum form a balanced heart over creamy sandalwood and musk.','women','women','powdery woody','autumn,winter','evening,office','Eau de Parfum',7,9,3,false,45),
  ('coastal-vetiver','Maison Sillage','فيتيفر الساحل','Coastal Vetiver','فيتيفر ترابي مع نسيم معدني وبرغموت.','Earthy vetiver with a mineral breeze and bergamot.','برغموت وقشر جريب فروت ينعشان فيتيفرًا ترابيًا ولمسة من خشب السرو.','Bergamot and grapefruit zest brighten earthy vetiver and a touch of cypress.','men','men','woody aromatic','spring,summer','day,travel','Eau de Parfum',6,8,3,false,40),
  ('pomegranate-noir','Maison Sillage','رمان داكن','Pomegranate Noir','رمان حامض وتوابل دافئة وقاعدة عنبرية.','Tart pomegranate, warm spice and an amber base.','رمان أسود ولمحة زعفران تفتتحان العطر، ثم يلتقي الباتشولي بالعنبر في نهاية داكنة أنيقة.','Black pomegranate and a hint of saffron open into patchouli and amber for an elegant dark finish.','unisex','unisex','fruity amber','autumn,winter','evening,occasion','Eau de Parfum',7,10,3,false,35),
  ('neroli-morning','Maison Sillage','صباح النيرولي','Neroli Morning','نيرولي مشمس وليمون وزهر برتقال شفاف.','Sunlit neroli, lemon and sheer orange blossom.','ليمون أخضر ونيرولي يفتحان رائحة زهرية هوائية، تكملها لمسة خفيفة من المسك.','Lime and neroli open an airy floral, finished with a light touch of musk.','women','women','citrus floral','spring,summer','day,travel','Eau de Toilette',4,6,2,false,30),
  ('smoked-cardamom','Maison Sillage','هيل مدخّن','Smoked Cardamom','هيل عطري ونفحة دخانية ولبان ناعم.','Aromatic cardamom, a smoky trace and soft incense.','هيل وفلفل وردي يفتتحان العطر، ثم يكشف اللبان وخشب الغاياك عن دفء دخاني لطيف.','Cardamom and pink pepper lead to incense and guaiac wood with a gentle smoky warmth.','men','men','spicy woody','autumn,winter','evening,occasion','Eau de Parfum',7,9,3,false,25),
  ('white-pepper-bloom','Maison Sillage','إزهار الفلفل الأبيض','White Pepper Bloom','فلفل أبيض وزنبق ومسك مضيء.','White pepper, lily and luminous musk.','انتعاش الفلفل الأبيض يسبق زنابق رقيقة وقاعدة من المسك النظيف وخشب الكشمير.','A crisp white pepper opening precedes delicate lily and clean musk over cashmere wood.','unisex','unisex','floral spicy','spring,autumn','day,office','Eau de Parfum',5,7,2,false,20),
  ('plum-suede','Maison Sillage','جلد البرقوق','Plum Suede','برقوق مخملي وجلد ناعم وخشب صندل.','Velvety plum, soft suede and sandalwood.','برقوق ناضج ولمسة زعفران فوق جلد نباتي ناعم، يوازنها الصندل والمسك.','Ripe plum and a hint of saffron sit over soft suede, balanced by sandalwood and musk.','women','women','fruity leather','autumn,winter','evening,occasion','Eau de Parfum',7,9,3,false,15),
  ('mineral-rain','Maison Sillage','مطر معدني','Mineral Rain','هواء ممطر وأوراق بنفسج وخشب أرز بارد.','Rain-washed air, violet leaf and cool cedar.','لمسة معدنية منعشة تتبعها أوراق البنفسج وخشب أرز رطب، مع قاعدة مسكية خفيفة.','A fresh mineral accord gives way to violet leaf and damp cedar over a light musky base.','unisex','unisex','aquatic woody','spring,summer','day,travel','Eau de Toilette',4,6,2,false,10),
  ('sandalwood-letter','Maison Sillage','رسالة الصندل','Sandalwood Letter','صندل كريمي مع ورق ناعم وفانيلا جافة.','Creamy sandalwood with soft paper and dry vanilla.','صندل دافئ يلتقي برائحة ورقية نظيفة ولمسة فانيلا جافة، في عطر قريب وحميم.','Warm sandalwood meets a clean paper accord and dry vanilla in an intimate, skin-close scent.','unisex','unisex','woody gourmand','autumn,winter','office,evening','Eau de Parfum',6,8,2,false,5),
  ('blue-hour-lavender','Maison Sillage','لافندر الساعة الزرقاء','Blue Hour Lavender','لافندر عطري وبرغموت وحبوب تونكا.','Aromatic lavender, bergamot and tonka bean.','لافندر نقي وحمضيات في البداية، ثم تظهر حبوب التونكا وخشب الأرز في قاعدة مريحة.','Clean lavender and citrus open before tonka and cedarwood form a comforting base.','men','men','aromatic fougere','spring,autumn','day,office','Eau de Parfum',6,8,3,false,4),
  ('orchid-shadow','Maison Sillage','ظل الأوركيد','Orchid Shadow','أوركيد هادئ مع كشمش أسود وخشب كريمي.','Quiet orchid with blackcurrant and creamy woods.','كشمش أسود خفيف يحيط بأوركيد ناعم، ثم يهدأ العطر على قاعدة من خشب الصندل والمسك.','A delicate blackcurrant accent surrounds soft orchid before fading into sandalwood and musk.','women','women','floral fruity','spring,autumn','day,occasion','Eau de Parfum',6,8,3,false,3),
  ('desert-bloom','Maison Sillage','زهر الصحراء','Desert Bloom','تمر مجفف وزهر صحراوي وعنبر دافئ.','Dried date, desert florals and warm amber.','نفحة تمر وزعفران تلتقي بزهور صحراوية وخشب العود الخفيف في قاعدة عنبرية.','Date and saffron meet desert florals and a trace of oud over a warm amber base.','unisex','unisex','amber floral','autumn,winter','evening,occasion','Extrait de Parfum',9,12,4,false,2),
  ('morning-basil','Maison Sillage','ريحان الصباح','Morning Basil','ريحان أخضر وليمون ومسك ناعم.','Green basil, lemon and soft musk.','ريحان طازج وقشر ليمون يفتحان تركيبة نهارية سهلة، مع قلب من النيرولي ومسك شفاف.','Fresh basil and lemon zest open an easy daytime blend with neroli and sheer musk.','men','men','green citrus','spring,summer','day,travel','Eau de Toilette',3,5,2,false,1)
), inserted_products as (
  insert into public.products (slug,brand,name_ar,name_en,short_description_ar,short_description_en,description_ar,description_en,category_id,gender,family,seasons,occasions,concentration,longevity_hours_min,longevity_hours_max,projection,status,featured,recommendation_enabled,priority,seo_title_ar,seo_title_en,seo_description_ar,seo_description_en)
  select c.slug,c.brand,c.name_ar,c.name_en,c.short_ar,c.short_en,c.description_ar,c.description_en,cat.id,c.gender,c.family,string_to_array(c.season,','),string_to_array(c.occasion,','),c.concentration,c.longevity_min,c.longevity_max,c.projection,'published',c.featured,true,c.priority,c.name_ar||' — ميزون سيلاج',c.name_en||' — Maison Sillage',c.short_ar,c.short_en
  from catalog c join public.categories cat on cat.slug=c.category_slug
  on conflict (slug) do update set brand=excluded.brand,name_ar=excluded.name_ar,name_en=excluded.name_en,short_description_ar=excluded.short_description_ar,short_description_en=excluded.short_description_en,description_ar=excluded.description_ar,description_en=excluded.description_en,category_id=excluded.category_id,gender=excluded.gender,family=excluded.family,seasons=excluded.seasons,occasions=excluded.occasions,concentration=excluded.concentration,longevity_hours_min=excluded.longevity_hours_min,longevity_hours_max=excluded.longevity_hours_max,projection=excluded.projection,status=excluded.status,featured=excluded.featured,recommendation_enabled=excluded.recommendation_enabled,priority=excluded.priority,seo_title_ar=excluded.seo_title_ar,seo_title_en=excluded.seo_title_en,seo_description_ar=excluded.seo_description_ar,seo_description_en=excluded.seo_description_en,updated_at=now()
  returning id,slug
)
select count(*) from inserted_products;

-- Three purchasable sizes per fragrance. Stock stays private behind server-side availability checks.
insert into public.product_variants(product_id,sku,size_ml,price_minor,compare_at_minor,stock_available,low_stock_threshold,active)
select p.id, upper(p.slug)||'-'||v.size_ml, v.size_ml, price_point.price, null, v.stock, 2, true
from public.products p
cross join lateral (values (30::numeric,1.0::numeric,8), (50::numeric,1.48::numeric,5), (100::numeric,2.2::numeric,3)) v(size_ml,multiplier,stock)
cross join lateral (select floor((55000000 + p.priority * 250000) * v.multiplier)::bigint as price) price_point
where p.slug in ('amber-veil','fig-at-dusk','rose-after-rain','cedar-atelier','salted-citrus','saffron-library','linen-musk','cocoa-ember','jasmine-courtyard','oud-horizon','green-tea-stillness','velvet-iris','coastal-vetiver','pomegranate-noir','neroli-morning','smoked-cardamom','white-pepper-bloom','plum-suede','mineral-rain','sandalwood-letter','blue-hour-lavender','orchid-shadow','desert-bloom','morning-basil')
on conflict(sku) do update set product_id=excluded.product_id,size_ml=excluded.size_ml,price_minor=excluded.price_minor,compare_at_minor=excluded.compare_at_minor,stock_available=excluded.stock_available,low_stock_threshold=excluded.low_stock_threshold,active=true,updated_at=now();

insert into public.product_images(product_id,storage_path,alt_ar,alt_en,sort_order)
select p.id,'assets/products/'||p.slug||'.svg',p.name_ar,p.name_en,0 from public.products p
where p.slug in ('amber-veil','fig-at-dusk','rose-after-rain','cedar-atelier','salted-citrus','saffron-library','linen-musk','cocoa-ember','jasmine-courtyard','oud-horizon','green-tea-stillness','velvet-iris','coastal-vetiver','pomegranate-noir','neroli-morning','smoked-cardamom','white-pepper-bloom','plum-suede','mineral-rain','sandalwood-letter','blue-hour-lavender','orchid-shadow','desert-bloom','morning-basil')
on conflict(storage_path) do update set product_id=excluded.product_id,alt_ar=excluded.alt_ar,alt_en=excluded.alt_en,sort_order=0;

insert into public.fragrance_notes(slug,name_ar,name_en) values
 ('bergamot','برغموت','Bergamot'),('jasmine','ياسمين','Jasmine'),('sandalwood','خشب الصندل','Sandalwood'),('amber','عنبر','Amber'),('vanilla','فانيلا','Vanilla'),('fig-leaf','ورق التين','Fig leaf'),('cardamom','هيل','Cardamom'),('iris','سوسن','Iris'),('cedar','أرز','Cedar'),('musk','مسك','Musk'),('rose','ورد','Rose'),('pink-pepper','فلفل وردي','Pink pepper'),('patchouli','باتشولي','Patchouli'),('lemon','ليمون','Lemon'),('sea-salt','ملح البحر','Sea salt'),('saffron','زعفران','Saffron'),('suede','جلد ناعم','Suede'),('cocoa','كاكاو','Cocoa'),('tonka','حبوب التونكا','Tonka bean'),('orange-blossom','زهر البرتقال','Orange blossom'),('oud','عود','Oud'),('green-tea','شاي أخضر','Green tea'),('neroli','نيرولي','Neroli'),('plum','برقوق','Plum'),('vetiver','فيتيفر','Vetiver'),('pomegranate','رمان','Pomegranate'),('incense','لبان','Incense'),('lavender','لافندر','Lavender'),('basil','ريحان','Basil'),('orchid','أوركيد','Orchid'),('date','تمر','Date'),('violet-leaf','ورق البنفسج','Violet leaf'),('cinnamon','قرفة','Cinnamon'),('grapefruit','جريب فروت','Grapefruit'),('cashmere-wood','خشب الكشمير','Cashmere wood')
on conflict(slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en;

with note_map(product_slug, top_notes, heart_notes, base_notes) as (values
 ('amber-veil','bergamot','jasmine','amber'),('fig-at-dusk','fig-leaf','iris','cedar'),('rose-after-rain','pink-pepper','rose','patchouli'),('cedar-atelier','bergamot','cardamom','cedar'),('salted-citrus','lemon','sea-salt','musk'),('saffron-library','saffron','suede','oud'),('linen-musk','bergamot','orange-blossom','musk'),('cocoa-ember','cocoa','cinnamon','tonka'),('jasmine-courtyard','orange-blossom','jasmine','sandalwood'),('oud-horizon','rose','oud','amber'),('green-tea-stillness','green-tea','neroli','cedar'),('velvet-iris','plum','iris','sandalwood'),('coastal-vetiver','grapefruit','cedar','vetiver'),('pomegranate-noir','pomegranate','saffron','amber'),('neroli-morning','lemon','neroli','musk'),('smoked-cardamom','cardamom','incense','cedar'),('white-pepper-bloom','pink-pepper','jasmine','cashmere-wood'),('plum-suede','plum','suede','sandalwood'),('mineral-rain','bergamot','violet-leaf','cedar'),('sandalwood-letter','bergamot','sandalwood','vanilla'),('blue-hour-lavender','bergamot','lavender','tonka'),('orchid-shadow','pomegranate','orchid','musk'),('desert-bloom','date','saffron','amber'),('morning-basil','lemon','basil','musk')
), layers as (select product_slug, unnest(array['top','heart','base']) layer, unnest(array[top_notes,heart_notes,base_notes]) note_slug from note_map)
insert into public.product_notes(product_id,note_id,layer)
select p.id,n.id,l.layer from layers l join public.products p on p.slug=l.product_slug join public.fragrance_notes n on n.slug=l.note_slug
on conflict(product_id,note_id,layer) do nothing;

insert into public.product_attributes(product_id,vector,profile_version,updated_at)
select p.id, jsonb_build_object(
  'woody',case when p.family like '%woody%' or p.family like '%oud%' or p.family like '%leather%' then 78 else 32 end,
  'floral',case when p.family like '%floral%' or p.family like '%chypre%' then 78 else 25 end,
  'fresh',case when p.family like '%citrus%' or p.family like '%green%' or p.family like '%aquatic%' or p.family like '%aromatic%' then 76 else 32 end,
  'sweet',case when p.family like '%gourmand%' or p.family like '%amber%' or p.family like '%fruity%' then 70 else 25 end,
  'warm',case when p.family like '%amber%' or p.family like '%spicy%' or p.family like '%oud%' then 76 else 34 end,
  'smoky',case when p.slug='smoked-cardamom' or p.family like '%leather%' then 62 else 18 end,
  'bold',case when p.concentration like '%Extrait%' or p.projection>=4 then 72 else 42 end,
  'calm',case when p.family like '%musky%' or p.family like '%green%' or p.family like '%citrus%' or p.family like '%aquatic%' then 70 else 34 end,
  'classic',case when p.family like '%chypre%' or p.family like '%fougere%' or p.family like '%oud%' then 68 else 42 end,
  'modern',case when p.family like '%fruity%' or p.family like '%aquatic%' or p.family like '%gourmand%' or p.family like '%citrus%' then 68 else 42 end,
  'day',case when p.occasions && array['day','office','travel'] then 72 else 30 end,
  'night',case when p.occasions && array['evening','occasion'] then 72 else 30 end
),1,now()
from public.products p where p.slug in ('amber-veil','fig-at-dusk','rose-after-rain','cedar-atelier','salted-citrus','saffron-library','linen-musk','cocoa-ember','jasmine-courtyard','oud-horizon','green-tea-stillness','velvet-iris','coastal-vetiver','pomegranate-noir','neroli-morning','smoked-cardamom','white-pepper-bloom','plum-suede','mineral-rain','sandalwood-letter','blue-hour-lavender','orchid-shadow','desert-bloom','morning-basil')
on conflict(product_id) do update set vector=excluded.vector,profile_version=excluded.profile_version,updated_at=now();

insert into private.store_settings(id) values (true) on conflict(id) do nothing;
insert into private.telegram_settings(id) values (true) on conflict(id) do nothing;

