insert into public.shipping_zones(slug,name_ar,name_en,fee_minor,active) values
  ('baghdad','بغداد','Baghdad',5000000,true),
  ('basra','البصرة','Basra',10000000,true),
  ('erbil','أربيل','Erbil',8000000,true)
